CREATE TABLE profiles (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, avatar TEXT NOT NULL DEFAULT 'violet', created_at INTEGER NOT NULL);
CREATE TABLE counters (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
INSERT INTO counters VALUES ('profile',0);
CREATE TABLE profile_preferences (profile_id TEXT PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE, data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE local_credentials (profile_id TEXT PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE, hash TEXT NOT NULL, must_change INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL, expires_at INTEGER NOT NULL, restricted INTEGER NOT NULL DEFAULT 0, user_agent TEXT NOT NULL DEFAULT '');
CREATE INDEX session_profile ON sessions(profile_id);
CREATE TABLE shows (id TEXT PRIMARY KEY, name TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', premiered TEXT NOT NULL DEFAULT '', network TEXT NOT NULL DEFAULT '', genres TEXT NOT NULL DEFAULT '[]', image TEXT NOT NULL DEFAULT '', rating REAL NOT NULL DEFAULT 0, runtime INTEGER NOT NULL DEFAULT 0, last_checked_at INTEGER NOT NULL DEFAULT 0, next_check_at INTEGER NOT NULL DEFAULT 0, last_changed_at INTEGER NOT NULL DEFAULT 0, provider_updated_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX shows_due ON shows(next_check_at);
CREATE TABLE seasons (id TEXT PRIMARY KEY, show_id TEXT NOT NULL REFERENCES shows(id) ON DELETE CASCADE, number INTEGER NOT NULL, name TEXT NOT NULL DEFAULT '', episode_count INTEGER NOT NULL DEFAULT 0, premiere_date TEXT NOT NULL DEFAULT '', end_date TEXT NOT NULL DEFAULT '', UNIQUE(show_id,number));
CREATE TABLE episodes (id TEXT PRIMARY KEY, show_id TEXT NOT NULL REFERENCES shows(id) ON DELETE CASCADE, season INTEGER NOT NULL, number INTEGER NOT NULL, name TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', airdate TEXT NOT NULL DEFAULT '', airstamp TEXT NOT NULL DEFAULT '', runtime INTEGER NOT NULL DEFAULT 0, type TEXT NOT NULL DEFAULT 'regular');
CREATE INDEX episode_air ON episodes(airdate);
CREATE INDEX episode_show ON episodes(show_id,season,number);
CREATE TABLE external_ids (provider TEXT NOT NULL, kind TEXT NOT NULL, external_id TEXT NOT NULL, internal_id TEXT NOT NULL, PRIMARY KEY(provider,kind,external_id), UNIQUE(provider,kind,internal_id));
CREATE TABLE profile_shows (profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, show_id TEXT NOT NULL REFERENCES shows(id) ON DELETE CASCADE, added_at INTEGER NOT NULL, PRIMARY KEY(profile_id,show_id));
CREATE TABLE profile_episode_state (profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, episode_id TEXT NOT NULL REFERENCES episodes(id) ON DELETE CASCADE, watched INTEGER NOT NULL DEFAULT 0 CHECK(watched IN (0,1)), downloaded INTEGER NOT NULL DEFAULT 0 CHECK(downloaded IN (0,1)), updated_at INTEGER NOT NULL, PRIMARY KEY(profile_id,episode_id));
CREATE TABLE jobs (key TEXT PRIMARY KEY, type TEXT NOT NULL, schedule TEXT NOT NULL, next_run INTEGER NOT NULL DEFAULT 0);
CREATE TABLE job_runs (id TEXT PRIMARY KEY, job_key TEXT NOT NULL, trigger TEXT NOT NULL, started_at INTEGER NOT NULL, ended_at INTEGER, duration_ms INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 1, error TEXT NOT NULL DEFAULT '', candidates INTEGER NOT NULL DEFAULT 0, processed INTEGER NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0, api_calls INTEGER NOT NULL DEFAULT 0, cache_hits INTEGER NOT NULL DEFAULT 0, changes INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_running_job ON job_runs(job_key) WHERE status='running';
CREATE TABLE provider_state (provider TEXT PRIMARY KEY, state TEXT NOT NULL DEFAULT 'healthy', failures INTEGER NOT NULL DEFAULT 0, window_start INTEGER NOT NULL DEFAULT 0, blocked_until INTEGER NOT NULL DEFAULT 0, open_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE provider_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, provider TEXT NOT NULL, trigger TEXT NOT NULL, entity TEXT NOT NULL DEFAULT '', job_id TEXT NOT NULL DEFAULT '', status_code INTEGER NOT NULL, reason TEXT NOT NULL, retry_count INTEGER NOT NULL DEFAULT 0, duration_ms INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX requests_created ON provider_requests(created_at);
CREATE TABLE provider_request_aggregates (day TEXT NOT NULL, provider TEXT NOT NULL, requests INTEGER NOT NULL DEFAULT 0, successes INTEGER NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, retries INTEGER NOT NULL DEFAULT 0, rate_limited INTEGER NOT NULL DEFAULT 0, cache_hits INTEGER NOT NULL DEFAULT 0, conditional_hits INTEGER NOT NULL DEFAULT 0, avoided INTEGER NOT NULL DEFAULT 0, latency_ms INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(day,provider));
CREATE TABLE alerts (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, level TEXT NOT NULL, message TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE backup_records (id TEXT PRIMARY KEY, filename TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, size INTEGER NOT NULL, created_at INTEGER NOT NULL, verified INTEGER NOT NULL DEFAULT 1);
CREATE TABLE torrent_search_history (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, query TEXT NOT NULL, provider TEXT NOT NULL, results INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE torrent_send_history (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, UNIQUE(profile_id,idempotency_key));
